-- ES/DE/FR translations for all 7 Norway milestones.
-- no-issue and no-receive reuse the tracker's own phrasing per
-- tracker-phrasing-wins.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-b2g-2019', 'es', 'Facturación electrónica B2G obligatoria a través de EHF/Peppol', 'Los organismos del sector público y sus proveedores deben utilizar EHF/Peppol BIS Billing 3.0 a través de la red Peppol — la infraestructura sobre la que se construye directamente el mandato B2B de 2027.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-b2g-2019', 'de', 'B2G-E-Rechnung über EHF/Peppol verpflichtend', 'Öffentliche Stellen und ihre Lieferanten müssen EHF/Peppol BIS Billing 3.0 über das Peppol-Netzwerk verwenden — die Infrastruktur, auf der die B2B-Pflicht von 2027 direkt aufbaut.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-b2g-2019', 'fr', 'Facturation électronique B2G obligatoire via EHF/Peppol', 'Les organismes du secteur public et leurs fournisseurs doivent utiliser EHF/Peppol BIS Billing 3.0 sur le réseau Peppol — l''infrastructure sur laquelle s''appuie directement l''obligation B2B de 2027.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-consultation-2024', 'es', 'Se publica la nota de consulta preliminar', 'El Ministerio de Finanzas publica una consulta inicial que examina la contabilidad y facturación digital obligatoria entre empresas, basada en un informe de la Dirección de Impuestos.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-consultation-2024', 'de', 'Vorläufiges Konsultationspapier veröffentlicht', 'Das Finanzministerium veröffentlicht eine erste Konsultation zur verpflichtenden digitalen Buchführung und Rechnungsstellung zwischen Unternehmen, basierend auf einem Bericht der Steuerdirektion.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-consultation-2024', 'fr', 'Note de consultation préliminaire publiée', 'Le ministère des Finances publie une première consultation examinant la comptabilité et la facturation numériques obligatoires entre entreprises, sur la base d''un rapport de la Direction des impôts.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-instruction-2026', 'es', 'El Ministerio instruye a Skattedirektoratet para preparar la normativa', 'Una carta de seguimiento pide a la Dirección de Impuestos que prepare modificaciones normativas detalladas sobre el formato de factura, los sistemas de contabilidad electrónica y posibles exenciones para pequeñas empresas.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-instruction-2026', 'de', 'Ministerium beauftragt Skattedirektoratet mit der Vorbereitung von Vorschriften', 'Ein Folgeschreiben bittet die Steuerdirektion, detaillierte regulatorische Änderungen zu Rechnungsformat, elektronischen Buchführungssystemen und möglichen Ausnahmen für Kleinunternehmen vorzubereiten.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-instruction-2026', 'fr', 'Le ministère charge Skattedirektoratet de préparer la réglementation', 'Une lettre de suivi demande à la Direction des impôts de préparer des modifications réglementaires détaillées concernant le format des factures, les systèmes de comptabilité électronique et d''éventuelles exemptions pour les petites entreprises.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-law-enacted-2026', 'es', 'La ley se promulga formalmente (Law-2026-06-19-39)', 'El Parlamento aprueba la Ley de Modificaciones a la Ley de Contabilidad y otras leyes en el ámbito de los mercados financieros, confirmando la transición de propuesta (Prop. 44 L) a régimen legal vinculante.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-law-enacted-2026', 'de', 'Gesetz formell erlassen (Law-2026-06-19-39)', 'Das Parlament verabschiedet das Gesetz zur Änderung des Buchführungsgesetzes und bestimmter anderer Gesetze im Bereich der Finanzmärkte und bestätigt den Übergang vom Vorschlag (Prop. 44 L) zum verbindlichen gesetzlichen Regime.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-law-enacted-2026', 'fr', 'La loi est formellement promulguée (Law-2026-06-19-39)', 'Le Parlement adopte la loi portant modification de la loi sur la comptabilité et de certaines autres lois dans le domaine des marchés financiers, confirmant la transition de la proposition (Prop. 44 L) à un régime légal contraignant.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-technical-detail-2026', 'es', 'Skattedirektoratet debe confirmar el detalle técnico restante', 'Las normas finales sobre las especificaciones del formato de factura, los criterios de los sistemas de contabilidad digital y cualquier exención o aplazamiento para pequeñas empresas deben estar listas para esta fecha.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-technical-detail-2026', 'de', 'Skattedirektoratet muss verbleibende technische Details bestätigen', 'Die endgültigen Regeln zu den Rechnungsformat-Spezifikationen, den Kriterien für digitale Buchführungssysteme sowie etwaigen Ausnahmen oder Aufschüben für Kleinunternehmen sind bis zu diesem Datum fällig.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-technical-detail-2026', 'fr', 'Skattedirektoratet doit confirmer les derniers détails techniques', 'Les règles définitives concernant les spécifications du format de facture, les critères des systèmes de comptabilité numérique et toute exemption ou report pour les petites entreprises doivent être prêtes à cette date.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-issue', 'es', 'Emisión obligatoria de facturas electrónicas B2B (EHF 3.0 / Peppol BIS)', 'Tras la promulgación de las modificaciones a la Ley de Contabilidad, todas las empresas con obligaciones contables noruegas deben emitir facturas electrónicas estructuradas (formato EHF) a otras empresas registradas en el directorio ELMA.', '["Regístrese en ELMA (el directorio noruego de destinatarios Peppol) si aún no figura en él", "Confirme que su software de facturación admite la emisión en EHF 3.0 / Peppol BIS", "Las facturas B2B en PDF y en papel dejarán de ser válidas para las transacciones incluidas en el alcance"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-issue', 'de', 'Verpflichtende B2B-E-Rechnungsstellung (EHF 3.0 / Peppol BIS)', 'Nach Inkrafttreten der Änderungen des Buchführungsgesetzes müssen alle Unternehmen mit norwegischen Buchführungspflichten strukturierte E-Rechnungen (EHF-Format) an andere im ELMA-Verzeichnis registrierte Unternehmen ausstellen.', '["Registrieren Sie sich bei ELMA (dem norwegischen Peppol-Empfängerverzeichnis), falls noch nicht gelistet", "Bestätigen Sie, dass Ihre Rechnungssoftware die Ausgabe in EHF 3.0 / Peppol BIS unterstützt", "PDF- und Papier-B2B-Rechnungen sind für betroffene Transaktionen nicht mehr gültig"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-issue', 'fr', 'Émission obligatoire de factures électroniques B2B (EHF 3.0 / Peppol BIS)', 'À la suite de la promulgation des modifications de la loi sur la comptabilité, toutes les entreprises soumises à des obligations comptables norvégiennes doivent émettre des factures électroniques structurées (format EHF) à destination d''autres entreprises enregistrées dans l''annuaire ELMA.', '["Inscrivez-vous à ELMA (l''annuaire norvégien des destinataires Peppol) si ce n''est pas déjà fait", "Vérifiez que votre logiciel de facturation prend en charge la sortie EHF 3.0 / Peppol BIS", "Les factures B2B au format PDF et papier ne seront plus valables pour les transactions concernées"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-receive', 'es', 'Recepción obligatoria de facturas electrónicas y contabilidad totalmente digital', 'El mandato se extiende a la recepción de facturas electrónicas estructuradas y al mantenimiento de registros contables totalmente digitales, completando la reforma noruega en dos fases.', '["Planifique la migración a un sistema de contabilidad digital aprobado con suficiente antelación a esta fecha", "Confirme que los sistemas de Punto de Acceso pueden recibir y procesar facturas EHF/Peppol de forma automática"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-receive', 'de', 'Verpflichtender E-Rechnungsempfang und vollständig digitale Buchführung', 'Die Pflicht wird auf den Empfang strukturierter E-Rechnungen und die Führung vollständig digitaler Buchführungsunterlagen ausgeweitet und schließt damit Norwegens zweiphasige Reform ab.', '["Planen Sie die Migration zu einem zugelassenen digitalen Buchführungssystem rechtzeitig vor diesem Datum", "Bestätigen Sie, dass Access-Point-Systeme EHF/Peppol-Rechnungen automatisch empfangen und verarbeiten können"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('no-receive', 'fr', 'Réception obligatoire des factures électroniques et comptabilité entièrement numérique', 'L''obligation s''étend à la réception de factures électroniques structurées et à la tenue d''une comptabilité entièrement numérique, achevant ainsi la réforme norvégienne en deux phases.', '["Planifiez la migration vers un système de comptabilité numérique agréé bien avant cette date", "Vérifiez que les systèmes d''Access Point peuvent recevoir et traiter automatiquement les factures EHF/Peppol"]');
